		refs:         make(map[string]webRefTarget),
		runs:         opts.RunControl,
		durable:      opts.DurableOperations,
		defaultModel: strings.TrimSpace(opts.DefaultModel),
		models:       opts.Models,
	}
	if _, err := rand.Read(u.secret[:]); err != nil {
