+func performanceVerificationRuntime(c config.Config) map[sprint.VerificationPhase]sprint.StageRuntime {
+	model := c.Planning.PerformanceModel
+	if strings.TrimSpace(model) == "" {
+		model = c.Models.Primary
+		if strings.TrimSpace(model) == "" {
+			model = c.Models.Default
+		}
+	}
+	variant := c.Planning.PerformanceVariant
+	if strings.TrimSpace(variant) == "" {
+		variant = c.Execution.DefaultVariant
+	}
+	return map[sprint.VerificationPhase]sprint.StageRuntime{
+		sprint.VerificationPhasePerformance: {Model: model, Variant: variant},
+	}
+}
+
+func performanceSettings(effective config.Effective) (sprint.PerformanceLimits, map[string]string, error) {
+	p := effective.Config.Performance
+	durations := []struct {
+		name  string
+		value string
+		dest  *time.Duration
+	}{}
+	limits := sprint.PerformanceLimits{TargetRows: p.TargetRows, AuthoringAttempts: p.AuthoringAttempts, OptimizationAttempts: p.OptimizationAttempts, Warmups: p.Warmups, SampleCeiling: p.SampleCeiling, CVPercent: p.CVPercent, Commands: p.Commands, StdoutBytes: p.StdoutBytes, StderrBytes: p.StderrBytes, ProfileBytes: p.ProfileBytes, ProposalBytes: p.ProposalBytes, ChangedFiles: p.ChangedFiles, ChangedBytes: p.ChangedBytes, OptimizationCycles: p.OptimizationCycles, RetainedAttempts: p.RetainedAttempts, EvidencePageSize: p.EvidencePageSize}
+	durations = append(durations, struct {
+		name, value string
+		dest        *time.Duration
+	}{"command_timeout", p.CommandTimeout, &limits.CommandTimeout}, struct {
+		name, value string
+		dest        *time.Duration
+	}{"wall_time", p.WallTime, &limits.WallTime}, struct {
+		name, value string
+		dest        *time.Duration
+	}{"cleanup_reserve", p.CleanupReserve, &limits.CleanupReserve})
+	for _, item := range durations {
+		value, err := time.ParseDuration(item.value)
+		if err != nil {
+			return limits, nil, fmt.Errorf("performance.%s: %w", item.name, err)
+		}
+		*item.dest = value
+	}
+	if err := sprint.ValidatePerformanceLimits(limits); err != nil {
+		return limits, nil, err
+	}
+	sources := map[string]string{}
+	for key, value := range effective.Sources {
+		if strings.HasPrefix(key, "performance.") {
+			sources[strings.TrimPrefix(key, "performance.")] = value
+		}
+	}
+	return limits, sources, nil
+}
